"""Read live Blosm objects into the Step 2 contract, without mutating them.

Use ``from_blosm_intersection(intersection, profiles_by_connector=..., ...)``
after Blosm has prepared its major Intersection/connectors. Profile design is
new input, keyed by the actual connector object or its source ``id``; it is not
guessed from OSM lane counts. Corner radii can be explicit, or resolved with the
actual ``wayCategoryProps`` mapping passed as ``category_properties``.

No imports of Blosm or bpy occur here: the adapter works inside the add-on and
can be tested against its actual model classes without running add-on setup.
"""
from .inputs import PreparedJunction, SectionInput, StreetInput, ConnectorInput, MemberInput, ProfileInput, STREET_ITEM, BUNDLE_ITEM, validate, validate_initial_scope


def _source_id(obj):
    value = getattr(obj, 'id', None)
    if not isinstance(value, int):
        raise ValueError(type(obj).__name__+' has no integer source id')
    return value


def _lookup(mapping, obj, label):
    try:
        return mapping[obj]
    except (KeyError, TypeError):
        try:
            return mapping[_source_id(obj)]
        except (KeyError, TypeError):
            raise ValueError('Missing '+label+' for connector '+str(_source_id(obj))) from None


def _connectors(intersection):
    start = getattr(intersection, 'startConnector', None)
    if start is None:
        raise ValueError('Intersection has no prepared connector ring')
    result, seen, current = [], set(), start
    while current is not None and id(current) not in seen:
        if getattr(current, 'intersection', None) is not intersection:
            raise ValueError('Connector references a different Intersection')
        if getattr(current, 'leaving', None) not in (True, False):
            raise ValueError('Connector leaving flag is not set')
        seen.add(id(current))
        result.append(current)
        successor = getattr(current, 'succ', None)
        if successor is None or getattr(successor, 'pred', None) is not current:
            raise ValueError('Connector ring has inconsistent predecessor links')
        current = successor
    if current is not start:
        raise ValueError('Connector ring does not close at its start')
    return result


def _section_chain(street):
    """Retain Section boundaries; refuse to misrepresent transition items."""
    sections, seen = [], set()
    current = getattr(street, 'head', None)
    tail = getattr(street, 'tail', None)
    while current is not None:
        if id(current) in seen:
            raise ValueError('Cyclic Street item chain')
        seen.add(id(current))
        # SideLane, SymLane, minor Intersection etc. have different semantics.
        # Their presence is an explicit unsupported result, never skipped.
        if type(current).__name__ != 'Section':
            raise ValueError('Initial adapter cannot export Street item '+type(current).__name__+
                             '; a transition-specific schema is required')
        if not getattr(current, 'valid', True):
            raise ValueError('Invalid source Section')
        sections.append(SectionInput(
            source_id=_source_id(current),
            centerline=tuple(tuple(float(x) for x in p) for p in current.centerline),
            width=float(current.width), offset=float(current.offset),
            category=str(current.category), chain_index=len(sections),
            tags=tuple(sorted(getattr(current, 'tags', {}).items()))))
        if current is tail:
            if getattr(current, 'succ', None) is not None:
                raise ValueError('Street tail unexpectedly has a successor item')
            break
        successor = getattr(current, 'succ', None)
        if successor is not None and getattr(successor, 'pred', None) is not current:
            raise ValueError('Street item chain has inconsistent predecessor links')
        current = successor
    if not sections or current is not tail:
        raise ValueError('Street head/tail do not define a complete Section chain')
    return tuple(sections)


def _member_leaving(street, intersection):
    start = getattr(getattr(street, 'pred', None), 'intersection', None) is intersection
    end = getattr(getattr(street, 'succ', None), 'intersection', None) is intersection
    if start == end:
        raise ValueError('Bundle member must have exactly one endpoint at this logical Intersection')
    return start


def _identity_index(sequence, obj):
    return next((i for i, item in enumerate(sequence) if item is obj), -1)


def from_blosm_intersection(intersection, *, profiles_by_connector,
                            corner_radii=None, category_properties=None,
                            right_hand_traffic=True, datum=0., cell_size=.7,
                            check_scope=True, section_reader=None, source_connectors=None,
                            separate_endpoint_incidences=False):
    """Adapt one major junction from live Section/Street/Bundle structures.

    ``profiles_by_connector`` maps connector objects or their source ids to
    ProfileInput values. ``corner_radii`` similarly specifies the corner after
    each connector in CCW order. If omitted, the radius is read from the relevant
    member Section category in ``category_properties``, using Blosm's existing
    right/left-hand-traffic policy. The first kernel uses
    one shared profile per connector; a Bundle's distinct member centerlines,
    widths, offsets and endpoint orientations remain separate geometry inputs.

    Source ids are provenance only. Dense indices are assigned by this export;
    class counters are not represented as stable identities across imports.
    Set check_scope=False only for inspecting/serializing data outside the first
    kernel's supported domain, not to ask that kernel to approximate it silently.
    A domain adapter may supply section_reader after explicitly accounting for
    non-geometric attachments in its own feature registry. The default remains
    strict; transition items must never be discarded by this function.
    A feature adapter may pass source_connectors to describe an explicit local
    surface boundary after separately accounting for junction-internal links.
    These must be distinct members of the unchanged original connector ring.
    This selection is not a coverage certificate for the omitted incidences.
    With separate_endpoint_incidences, the two authored ends of a returning
    Street receive distinct local table rows with the same original source IDs.
    The network compiler still owns its full original Section geometry once.
    Repeating the same authored endpoint remains invalid. This option enables
    incidence transport, not a geometric qualification of the returning path.
    """
    if getattr(intersection, 'isMinor', False):
        raise ValueError('Minor junctions in Street chains require a future adapter')
    sources = _connectors(intersection)
    if source_connectors is not None:
        selected=tuple(source_connectors)
        if len({id(c) for c in selected})!=len(selected) or not {id(c) for c in selected}<={id(c) for c in sources}:
            raise ValueError('Selected connectors must be distinct incidences from the original ring')
        sources=selected
    streets, street_lookup, profiles, connectors = [], {}, [], []
    bundles = {}
    for ordinal,connector in enumerate(sources):
        item = getattr(connector, 'item', None)
        if item is None:
            raise ValueError('Connector has no prepared Street or Bundle')
        is_bundle = hasattr(item, 'streetsHead') and hasattr(item, 'streetsTail')
        if is_bundle:
            members = list(item.streetsHead if connector.leaving else item.streetsTail)
            if id(item) not in bundles:
                bundles[id(item)] = len(bundles)
            bundle_index = bundles[id(item)]
        elif hasattr(item, 'head') and hasattr(item, 'tail'):
            members, bundle_index = [item], -1
        else:
            raise ValueError('Unsupported connector item '+type(item).__name__)
        if not members:
            raise ValueError('Bundle has no members at its connected end')
        prepared_members = []
        for order, street in enumerate(members):
            leaving = _member_leaving(street, intersection) if is_bundle else bool(connector.leaving)
            key = (id(street), leaving) if separate_endpoint_incidences else id(street)
            if key not in street_lookup:
                street_lookup[key] = len(streets)
                streets.append(StreetInput(_source_id(street),
                    (section_reader or _section_chain)(street)))
            if not is_bundle:
                reference = street.pred if leaving else street.succ
                if reference is not connector:
                    raise ValueError('Street endpoint connector does not match Intersection ring')
            prepared_members.append(MemberInput(
                street_index=street_lookup[key], leaving=leaving,
                lateral_order=order, bundle_index=bundle_index,
                head_order=_identity_index(item.streetsHead, street) if is_bundle else -1,
                tail_order=_identity_index(item.streetsTail, street) if is_bundle else -1))
        profile = _lookup(profiles_by_connector, connector, 'profile design')
        if not isinstance(profile, ProfileInput):
            raise ValueError('Profile design values must be ProfileInput objects')
        profile_index = len(profiles)
        profiles.append(profile)
        if corner_radii is not None:
            radius = float(_lookup(corner_radii, connector, 'corner radius'))
        else:
            if category_properties is None:
                raise ValueError('Supply explicit corner_radii or Blosm wayCategoryProps as category_properties')
            # This record specifies the corner from current to successor. Blosm
            # takes its category radius from the first polyline for right-hand
            # traffic, and the second for left-hand traffic. Respect the same
            # extreme-member selections used by its Bundle corner renderer.
            radius_connector = connector if right_hand_traffic else sources[(ordinal+1)%len(sources)]
            radius_item = radius_connector.item
            radius_bundle = hasattr(radius_item, 'streetsHead') and hasattr(radius_item, 'streetsTail')
            if radius_bundle:
                radius_members = radius_item.streetsHead if radius_connector.leaving else radius_item.streetsTail
                member_index = (0 if radius_connector.leaving else -1) if right_hand_traffic else (-1 if radius_connector.leaving else 0)
                radius_member = radius_members[member_index]
            else:
                radius_member = radius_item
            radius_leaving = _member_leaving(radius_member, intersection) if radius_bundle else bool(radius_connector.leaving)
            section = radius_member.head if radius_leaving else radius_member.tail
            try:
                radius = float(category_properties[section.category]['radius'])
            except KeyError:
                raise ValueError('No corner radius policy for category '+str(section.category)) from None
        connectors.append(ConnectorInput(
            source_id=_source_id(connector), members=tuple(prepared_members),
            profile_index=profile_index, radius=radius,
            item_kind=BUNDLE_ITEM if is_bundle else STREET_ITEM,
            leaving=bool(connector.leaving),
            bundle_source_id=_source_id(item) if is_bundle else -1))
    result = PreparedJunction(
        source_id=_source_id(intersection), location=tuple(intersection.location),
        streets=tuple(streets), connectors=tuple(connectors), profiles=tuple(profiles),
        datum=float(datum), cell_size=float(cell_size))
    (validate_initial_scope if check_scope else validate)(result)
    return result
